var i=`pacelc-theorem`;var o=42;var r={en:[{id:`T042-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`PACELC Theorem`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`BASE describes a family of distributed-system trade-offs often summarized as Basically Available, Soft state and Eventual consistency.`},{id:`B`,text:`A circuit breaker prevents repeated calls to an unhealthy dependency from exhausting resources and cascading failures.`},{id:`C`,text:`An operation is idempotent when applying it more than once has the same intended effect as applying it once.`},{id:`D`,text:`PACELC extends CAP: if partitioned, choose between availability and consistency; else, even in normal operation, choose between latency and consistency.`}]},{id:`T042-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`PACELC Theorem`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Study quorums, leader election, replicated logs, safety versus liveness, and fault models.`},{id:`B`,text:`A strongly consistent cross-region read may require waiting for remote coordination, while a local replica responds faster with possible staleness.`},{id:`C`,text:`Define failure thresholds, observation windows, reset timeouts and probe traffic.`},{id:`D`,text:`Use asynchronous replication, derived views and reconciliation rules to keep serving useful operations.`}]},{id:`T042-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`PACELC Theorem`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`},{id:`B`,text:`An order transaction creates a payment record and deducts store credit in one commit. If the write fails, neither partial operation should become visible as successful.`},{id:`C`,text:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage. A social feed might keep serving slightly stale content.`},{id:`D`,text:`A distributed configuration store can use Raft so nodes agree on the order of config updates. Application servers read committed state instead of inventing their own leader election protocol.`}]},{id:`T042-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`PACELC Theorem`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Long-running sagas expose temporary inconsistency.`},{id:`B`,text:`Do not classify every database permanently as CA, CP or AP; behavior is operation-specific and depends on fault assumptions.`},{id:`C`,text:`PACELC is a heuristic, not a complete specification of real systems.`},{id:`D`,text:`Wrong thresholds can trip on harmless fluctuations or keep calling a failing service.`}]},{id:`T042-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It captures everyday cost of coordination.`}]}]},{id:`T042-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`PACELC ignores latency whenever the network is healthy.`}]}]},{id:`T042-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Topology, caches, quorum settings and failure detection affect observed behavior; benchmark realistic networks.`}]}]},{id:`T042-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`PACELC Theorem`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A POST request is automatically idempotent if the server returns HTTP 200.`},{id:`B`,text:`A strongly consistent cross-region read may require waiting for remote coordination, while a local replica responds faster with possible staleness.`},{id:`C`,text:`PACELC extends CAP: if partitioned, choose between availability and consistency; else, even in normal operation, choose between latency and consistency.`},{id:`D`,text:`When no partition exists, PACELC makes no consistency-latency trade-off.`}]},{id:`T042-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`PACELC Theorem`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Topology, caches, quorum settings and failure detection affect observed behavior; benchmark realistic networks.`},{id:`B`,text:`PACELC ignores latency whenever the network is healthy.`},{id:`C`,text:`Circuit breakers make sense only after an upstream service is permanently dead.`},{id:`D`,text:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`}]},{id:`T042-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Have an agent design an order-payment-fulfillment saga with a state machine, idempotent steps, compensation table and an operator recovery procedure.`},{id:`B`,text:`Ask an agent to design reservation confirmation under a simulated partition, specifying exact success, timeout and retry semantics rather than a generic CP/AP label.`},{id:`C`,text:`Ask an agent to wrap an unreliable provider with timeout, circuit breaker and metrics. Test transitions across healthy, degraded and recovering states.`},{id:`D`,text:`Have an agent compare local stale reads and quorum reads for a two-region booking search. Require latency budgets, stale-data tolerance and an operational fallback.`}]},{id:`T042-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Where could eventual consistency reduce latency without compromising a business invariant?`}]}]},{id:`T042-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`PACELC Theorem`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T042-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`,b:!0},{t:` — propose three checks for `},{t:`PACELC Theorem`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T042-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T042-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`PACELC Theorem`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T042-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Теорема PACELC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`BASE описує компроміси розподілених систем: Basically Available, Soft state та Eventual consistency.`},{id:`B`,text:`Circuit Breaker припиняє повторні звернення до несправної залежності, щоб не виснажити ресурси й не запустити каскад відмов.`},{id:`C`,text:`Операція ідемпотентна, коли багаторазове виконання має той самий очікуваний ефект, що й одноразове.`},{id:`D`,text:`PACELC розширює CAP: за partition постає вибір між доступністю й узгодженістю; в нормальному режимі — між затримкою й узгодженістю.`}]},{id:`T042-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Теорема PACELC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Вивчайте quorum, вибори лідера, репліковані журнали, safety й liveness та моделі збоїв.`},{id:`B`,text:`Сильно узгоджене читання між регіонами може чекати віддаленої координації, тоді як локальна репліка відповідає швидше, але іноді застаріло.`},{id:`C`,text:`Визначте пороги помилок, вікно спостереження, час повторної перевірки та пробні запити.`},{id:`D`,text:`Використовуйте асинхронну реплікацію, похідні представлення й правила звірки для доступності операцій.`}]},{id:`T042-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Теорема PACELC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`},{id:`B`,text:`Транзакція замовлення створює запис платежу та списує кредит магазину одним commit. Якщо запис не вдався, жоден частковий результат не має вважатися успіхом.`},{id:`C`,text:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою. Соціальна стрічка може продовжувати віддавати трохи застарілі дані.`},{id:`D`,text:`Розподілене сховище конфігурації може використовувати Raft, щоб вузли погодили порядок оновлень. Сервери застосунку читають committed стан замість власного саморобного протоколу виборів.`}]},{id:`T042-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Теорема PACELC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Тривала saga має проміжну неузгодженість.`},{id:`B`,text:`Не навішуйте назавжди ярлик CA, CP чи AP на будь-яку БД: поведінка залежить від операцій і моделі відмов.`},{id:`C`,text:`PACELC — евристика, а не повна специфікація системи.`},{id:`D`,text:`Неправильні пороги реагують на дрібні коливання або надто довго викликають зламаний сервіс.`}]},{id:`T042-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Так видно повсякденну ціну координації.`}]}]},{id:`T042-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`PACELC ігнорує затримку, коли мережа працює нормально.`}]}]},{id:`T042-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Топологія, кеші, quorum і виявлення збоїв впливають на поведінку; потрібні вимірювання в реальних мережевих умовах.`}]}]},{id:`T042-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Теорема PACELC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`POST-запит автоматично ідемпотентний, якщо сервер повертає HTTP 200.`},{id:`B`,text:`Сильно узгоджене читання між регіонами може чекати віддаленої координації, тоді як локальна репліка відповідає швидше, але іноді застаріло.`},{id:`C`,text:`PACELC розширює CAP: за partition постає вибір між доступністю й узгодженістю; в нормальному режимі — між затримкою й узгодженістю.`},{id:`D`,text:`Коли розділення немає, PACELC не описує компроміс узгодженості й затримки.`}]},{id:`T042-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Теорема PACELC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Топологія, кеші, quorum і виявлення збоїв впливають на поведінку; потрібні вимірювання в реальних мережевих умовах.`},{id:`B`,text:`PACELC ігнорує затримку, коли мережа працює нормально.`},{id:`C`,text:`Circuit Breaker потрібен лише після остаточного виходу залежного сервісу з ладу.`},{id:`D`,text:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`}]},{id:`T042-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента створити saga замовлення, оплати й доставки зі станами, ідемпотентними кроками, таблицею компенсацій та процедурою ручного відновлення.`},{id:`B`,text:`Попросіть агента спроєктувати підтвердження бронювання під час мережевого розділення, явно визначити успіх, timeout і повтори замість загальної позначки CP/AP.`},{id:`C`,text:`Попросіть агента обгорнути нестабільного провайдера timeout, Circuit Breaker і метриками. Протестуйте переходи між нормою, деградацією та відновленням.`},{id:`D`,text:`Попросіть агента порівняти локальні застарілі читання з quorum для пошуку бронювань у двох регіонах. Вимагайте бюджети затримки, допустиму неактуальність і fallback.`}]},{id:`T042-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Де eventual consistency зменшить затримку, не порушуючи бізнес-інваріант?`}]}]},{id:`T042-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Теорема PACELC`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T042-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Теорема PACELC`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T042-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T042-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Теорема PACELC`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:42,questions:r};export{n as default,r as questions,i as slug,o as topicId};